import{_ as l,a0 as d,w as o,s as g,I as i,x as a,a1 as n,A as t,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 LVM 升级 Fedora | LCTT x X-CMD","titleTemplate":false,"description":"使用 LVM 升级 Fedora | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 LVM 升级 Fedora | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 LVM 升级 Fedora | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20180622 Use LVM to Upgrade Fedora","title":"使用 LVM 升级 Fedora","tag":"201908","desc":""},"relativePath":"201908/20180622 Use LVM to Upgrade Fedora.md","filePath":"[post].md"}'),r={name:"201908/20180622 Use LVM to Upgrade Fedora.md"};function h(c,s,u,k,b,f){const e=d("Link");return o(),g("div",null,[s[21]||(s[21]=i("h1",{id:"使用-lvm-升级-fedora",tabindex:"-1"},[a("使用 LVM 升级 Fedora "),i("a",{class:"header-anchor",href:"#使用-lvm-升级-fedora","aria-label":"Permalink to “使用 LVM 升级 Fedora”"},"​")],-1)),s[22]||(s[22]=i("p",null,[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/06/lvm-upgrade-816x345.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=a("大多数用户发现使用标准流程升级",-1)),n(e,{href:"https://fedoramagazine.org/upgrading-fedora-27-fedora-28/"},{default:t(()=>[...s[0]||(s[0]=[a("从一个 Fedora 版本升级到下一个",-1)])]),_:1}),s[2]||(s[2]=a("很简单。但是，Fedora 升级也不可避免地会遇到许多特殊情况。本文介绍了使用 DNF 和逻辑卷管理（LVM）进行升级的一种方法，以便在出现问题时保留可引导备份。这个例子是将 Fedora 26 系统升级到 Fedora 28。",-1))]),s[23]||(s[23]=p(`<p>此处展示的过程比标准升级过程更复杂。在使用此过程之前，你应该充分掌握 LVM 的工作原理。如果没有适当的技能和细心，你可能会丢失数据和/或被迫重新安装系统！如果你不知道自己在做什么，那么<strong>强烈建议</strong>你坚持只使用得到支持的升级方法。</p><h3 id="准备系统" tabindex="-1">准备系统 <a class="header-anchor" href="#准备系统" aria-label="Permalink to “准备系统”">​</a></h3><p>在开始之前，请确保你的现有系统已完全更新。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf update</span></span>
<span class="line"><span>$ sudo systemctl reboot # 或采用 GUI 方式</span></span></code></pre></div><p>检查你的根文件系统是否是通过 LVM 挂载的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df /</span></span>
<span class="line"><span>Filesystem              1K-blocks   Used        Available   Use%    Mounted on</span></span>
<span class="line"><span>/dev/mapper/vg_sdg-f26  20511312    14879816    4566536     77%     /</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo lvs</span></span>
<span class="line"><span>LV        VG            Attr        LSize Pool Origin Data% Meta% Move Log Cpy%Sync Convert</span></span>
<span class="line"><span>f22       vg_sdg        -wi-ao----  15.00g</span></span>
<span class="line"><span>f24_64    vg_sdg        -wi-ao----  20.00g</span></span>
<span class="line"><span>f26       vg_sdg        -wi-ao----  20.00g</span></span>
<span class="line"><span>home      vg_sdg        -wi-ao---- 100.00g</span></span>
<span class="line"><span>mockcache vg_sdg        -wi-ao----  10.00g</span></span>
<span class="line"><span>swap      vg_sdg        -wi-ao----   4.00g</span></span>
<span class="line"><span>test      vg_sdg        -wi-a-----   1.00g</span></span>
<span class="line"><span>vg_vm     vg_sdg        -wi-ao----  20.00g</span></span></code></pre></div><p>如果你在安装 Fedora 时使用了默认值，你可能会发现根文件系统挂载在名为 <code>root</code> 的逻辑卷（LV）上。卷组（VG）的名称可能会有所不同。看看根卷的总大小。在该示例中，根文件系统名为 <code>f26</code>，大小为 <code>20G</code>。</p><p>接下来，确保 LVM 中有足够的可用空间。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgs</span></span>
<span class="line"><span>VG      #PV #LV #SN Attr    VSize   VFree</span></span>
<span class="line"><span>vg_sdg  1   8   0   wz--n-  232.39g 42.39g</span></span></code></pre></div><p>该系统有足够的可用空间，可以为升级后的 Fedora 28 的根卷分配 20G 的逻辑卷。如果你使用的是默认安装，则你的 LVM 中将没有可用空间。对 LVM 的一般性管理超出了本文的范围，但这里有一些情形下可能采取的方法：</p><p>1、<code>/home</code> 在自己的逻辑卷，而且 <code>/home</code> 中有大量空闲空间。</p><p>你可以从图形界面中注销并切换到文本控制台，以 <code>root</code> 用户身份登录。然后你可以卸载 <code>/home</code>，并使用 <code>lvreduce -r</code> 调整大小并重新分配 <code>/home</code> 逻辑卷。你也可以从<ruby>现场镜像<rt>Live image</rt></ruby>启动（以便不使用 <code>/home</code>）并使用 gparted GUI 实用程序进行分区调整。</p><p>2、大多数 LVM 空间被分配给根卷，该文件系统中有大量可用空间。</p><p>你可以从现场镜像启动并使用 gparted GUI 实用程序来减少根卷的大小。此时也可以考虑将 <code>/home</code> 移动到另外的文件系统，但这超出了本文的范围。</p><p>3、大多数文件系统已满，但你有个已经不再需要逻辑卷。</p><p>你可以删除不需要的逻辑卷，释放卷组中的空间以进行此操作。</p><h3 id="创建备份" tabindex="-1">创建备份 <a class="header-anchor" href="#创建备份" aria-label="Permalink to “创建备份”">​</a></h3><p>首先，为升级后的系统分配新的逻辑卷。确保为系统的卷组（VG）使用正确的名称。在这个例子中它是 <code>vg_sdg</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvcreate -L20G -n f28 vg_sdg</span></span>
<span class="line"><span>Logical volume &quot;f28&quot; created.</span></span></code></pre></div><p>接下来，创建当前根文件系统的快照。此示例创建名为 <code>f26_s</code> 的快照卷。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sync</span></span>
<span class="line"><span>$ sudo lvcreate -s -L1G -n f26_s vg_sdg/f26</span></span>
<span class="line"><span>Using default stripesize 64.00 KiB.</span></span>
<span class="line"><span>Logical volume &quot;f26_s&quot; created.</span></span></code></pre></div><p>现在可以将快照复制到新逻辑卷。当你替换自己的卷名时，<strong>请确保目标正确</strong>。如果不小心，就会不可撤销地删除了数据。此外，请确保你从根卷的快照复制，<strong>而不是</strong>从你的现在的根卷。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dd if=/dev/vg_sdg/f26_s of=/dev/vg_sdg/f28 bs=256k</span></span>
<span class="line"><span>81920+0 records in</span></span>
<span class="line"><span>81920+0 records out</span></span>
<span class="line"><span>21474836480 bytes (21 GB, 20 GiB) copied, 149.179 s, 144 MB/s</span></span></code></pre></div><p>给新文件系统一个唯一的 UUID。这不是绝对必要的，但 UUID 应该是唯一的，因此这避免了未来的混淆。以下是在 ext4 根文件系统上的方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo e2fsck -f /dev/vg_sdg/f28</span></span>
<span class="line"><span>$ sudo tune2fs -U random /dev/vg_sdg/f28</span></span></code></pre></div><p>然后删除不再需要的快照卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvremove vg_sdg/f26_s</span></span>
<span class="line"><span>Do you really want to remove active logical volume vg_sdg/f26_s? [y/n]: y</span></span>
<span class="line"><span>Logical volume &quot;f26_s&quot; successfully removed</span></span></code></pre></div><p>如果你单独挂载了 <code>/home</code>，你可能希望在此处制作 <code>/home</code> 的快照。有时，升级的应用程序会进行与旧版 Fedora 版本不兼容的更改。如果需要，编辑<strong>旧</strong>根文件系统上的 <code>/etc/fstab</code> 文件以在 <code>/home</code> 上挂载快照。请记住，当快照已满时，它将消失！另外，你可能还希望给 <code>/home</code> 做个正常备份。</p><h3 id="配置以使用新的根" tabindex="-1">配置以使用新的根 <a class="header-anchor" href="#配置以使用新的根" aria-label="Permalink to “配置以使用新的根”">​</a></h3><p>首先，安装新的逻辑卷并备份现有的 GRUB 设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /mnt/f28</span></span>
<span class="line"><span>$ sudo mount /dev/vg_sdg/f28 /mnt/f28</span></span>
<span class="line"><span>$ sudo mkdir /mnt/f28/f26</span></span>
<span class="line"><span>$ cd /boot/grub2</span></span>
<span class="line"><span>$ sudo cp -p grub.cfg grub.cfg.old</span></span></code></pre></div><p>编辑 <code>grub.conf</code> 并在第一个菜单项 <code>menuentry</code> 之前添加这些，除非你已经有了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>menuentry &#39;Old boot menu&#39; {</span></span>
<span class="line"><span>  configfile /grub2/grub.cfg.old</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编辑 <code>grub.conf</code> 并更改默认菜单项以激活并挂载新的根文件系统。改变这一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linux16 /vmlinuz-4.16.11-100.fc26.x86_64 root=/dev/mapper/vg_sdg-f26 ro rd.lvm.lv=vg_sdg/f26 rd.lvm.lv=vg_sdg/swap rhgb quiet LANG=en_US.UTF-8</span></span></code></pre></div><p>如你看到的这样。请记住使用你系统上的正确的卷组和逻辑卷条目名称！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linux16 /vmlinuz-4.16.11-100.fc26.x86_64 root=/dev/mapper/vg_sdg-f28 ro rd.lvm.lv=vg_sdg/f28 rd.lvm.lv=vg_sdg/swap rhgb quiet LANG=en_US.UTF-8</span></span></code></pre></div><p>编辑 <code>/mnt/f28/etc/default/grub</code> 并改变在启动时激活的默认的根卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GRUB_CMDLINE_LINUX=&quot;rd.lvm.lv=vg_sdg/f28 rd.lvm.lv=vg_sdg/swap rhgb quiet&quot;</span></span></code></pre></div><p>编辑 <code>/mnt/f28/etc/fstab</code>，将挂载的根文件系统从旧的逻辑卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/mapper/vg_sdg-f26 / ext4 defaults 1 1</span></span></code></pre></div><p>改为新的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/mapper/vg_sdg-f28 / ext4 defaults 1 1</span></span></code></pre></div><p>然后，出于参考的用途，只读挂载旧的根卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/mapper/vg_sdg-f26 /f26 ext4 ro,nodev,noexec 0 0</span></span></code></pre></div><p>如果你的根文件系统是通过 UUID 挂载的，你需要改变这个方式。如果你的根文件系统是 ext4 你可以这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo e2label /dev/vg_sdg/f28 F28</span></span></code></pre></div><p>现在编辑 <code>/mnt/f28/etc/fstab</code> 使用该卷标。改变该根文件系统的挂载行，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LABEL=F28 / ext4 defaults 1 1</span></span></code></pre></div><h3 id="重启与升级" tabindex="-1">重启与升级 <a class="header-anchor" href="#重启与升级" aria-label="Permalink to “重启与升级”">​</a></h3><p>重新启动，你的系统将使用新的根文件系统。它仍然是 Fedora 26，但是是带有新的逻辑卷名称的副本，并可以进行 <code>dnf</code> 系统升级！如果出现任何问题，请使用旧引导菜单引导回到你的工作系统，此过程可避免触及旧系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl reboot # or GUI equivalent</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>$ df / /f26</span></span>
<span class="line"><span>Filesystem 1K-blocks Used Available Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/vg_sdg-f28 20511312 14903196 4543156 77% /</span></span>
<span class="line"><span>/dev/mapper/vg_sdg-f26 20511312 14866412 4579940 77% /f26</span></span></code></pre></div><p>你可能希望验证使用旧的引导菜单确实可以让你回到挂载在旧的根文件系统上的根。</p>`,53)),i("p",null,[s[4]||(s[4]=a("现在按照",-1)),n(e,{href:"https://fedoraproject.org/wiki/DNF_system_upgrade"},{default:t(()=>[...s[3]||(s[3]=[a("此维基页面",-1)])]),_:1}),s[5]||(s[5]=a("中的说明进行操作。如果系统升级出现任何问题，你还会有一个可以重启回去的工作系统。",-1))]),s[24]||(s[24]=p('<h3 id="进一步的考虑" tabindex="-1">进一步的考虑 <a class="header-anchor" href="#进一步的考虑" aria-label="Permalink to “进一步的考虑”">​</a></h3><p>创建新的逻辑卷并将根卷的快照复制到其中的步骤可以使用通用脚本自动完成。它只需要新的逻辑卷的名称，因为现有根的大小和设备很容易确定。例如，可以输入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo copyfs / f28</span></span></code></pre></div><p>提供挂载点以进行复制可以更清楚地了解发生了什么，并且复制其他挂载点（例如 <code>/home</code>）可能很有用。</p><hr>',5)),i("p",null,[s[7]||(s[7]=a("via: ",-1)),n(e,{href:"https://fedoramagazine.org/use-lvm-upgrade-fedora/"},{default:t(()=>[...s[6]||(s[6]=[a("https://fedoramagazine.org/use-lvm-upgrade-fedora/",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("作者：",-1)),n(e,{href:"https://fedoramagazine.org/author/sdgathman/"},{default:t(()=>[...s[8]||(s[8]=[a("Stuart D Gathman",-1)])]),_:1}),s[13]||(s[13]=a(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[9]||(s[9]=[a("lujun9972",-1)])]),_:1}),s[14]||(s[14]=a(" 译者：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1}),s[15]||(s[15]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[17]||(s[17]=[a("Linux中国",-1)])]),_:1}),s[20]||(s[20]=a(" 荣誉推出",-1))])])}const C=l(r,[["render",h]]);export{y as __pageData,C as default};
